function attendanceDate(value){const t=String(value??'').trim();if(/^\d{5}(\.\d+)?$/.test(t))return new Date(Date.UTC(1899,11,30)+Math.floor(Number(t))*86400000).toISOString().slice(0,10);if(/^\d{4}-\d{2}-\d{2}/.test(t))return t.slice(0,10);const m=t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})(?:\s|$)/);return m?`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`:''}
