function attendanceNotice(a,s){const check=attendanceCheck(a,s);if(!check)return '';const label=({baja:'Baja',present:'Asistió',absent:'Faltó',justified:'Falta justificada',unknown:'Sin dato'})[check.state];return `<section class="attendance-panel attendance-${check.state} review-attendance-compact" aria-label="Asistencia el día de la práctica"><div class="review-attendance-summary"><span class="attendance-heading">Asistencia</span><strong>${esc(label)}</strong><span>${a.classAt?esc(new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(a.classAt+'T00:00:00Z'))):'Falta indicar la fecha de clase'}</span></div><details class="review-attendance-details"><summary>Detalles y ajustes</summary><div>${check.mark?`<p>Marca en la lista: <strong>${esc(check.mark)}</strong></p>`:''}<p>Solo informativo: se consulta el día de clase y no modifica la nota.</p><div class="attendance-actions"><button id="reviewClassDate" type="button">${a.classAt?'Cambiar día de práctica':'Indicar día de práctica'}</button></div></div></details>${attendanceNeedsUpdate(a,s)?'<div class="review-attendance-update"><span>La lista aún no cubre el día de esta práctica.</span><button id="reviewAttendanceImport" type="button">Actualizar lista</button></div>':''}</section>`}

