function activityBatchImport(input){if(input.format!=='aula-config'||input.version!==1||input.kind!=='activities'||!Array.isArray(input.data)||!input.data.length||input.data.length>100)throw Error('Lote de actividades inválido.');const entries=Aula.clone(input.data);for(const a of entries){if(!a.name?.trim()||!['Práctica','Tarea'].includes(a.type)||a.requiresSignature!==false&&a.requiresSignature!==true)throw Error('Revisa nombres, tipos y firma del lote.');for(const key of ['classAt','dueAt'])if(a[key]&&Aula.dateDay(a[key])===null)throw Error('Fecha inválida en '+a.name)}const available=list('groups').filter(g=>subjects().some(s=>s.id===g.subjectId)),matches=available.filter(g=>Aula.norm(g.name)===Aula.norm(input.defaults?.groupName)&&(!input.defaults?.subjectName||Aula.norm(db.subjects.find(s=>s.id===g.subjectId)?.name)===Aula.norm(input.defaults.subjectName)));let target=matches.length===1?matches[0].id:'';closeModal();dialog('Precargar actividades',`<p class="muted">${entries.length} actividades. Los datos de apertura y cierre se conservan como referencia de Moodle. Las fechas de clase y límite que no están confirmadas pueden completarse después.</p><label for="batchImportGroup">Grupo y materia de destino</label><select id="batchImportGroup">${options(available.map(g=>({id:g.id,name:g.name+' · '+db.subjects.find(s=>s.id===g.subjectId)?.name})),target,'Selecciona el grupo')}</select><div class="columns"><div><label for="batchImportPeriod">Parcial</label><select id="batchImportPeriod"></select></div><div><label for="batchImportCategory">Categoría</label><select id="batchImportCategory"></select></div></div><label class="check"><input type="checkbox" id="batchUpdateExisting"> Actualizar solo las fechas de actividades con el mismo código (conservar cotejos, firmas y calificaciones)</label><div class="import-table"><table><thead><tr><th>Actividad</th><th>Día de clase</th><th>Fecha límite</th></tr></thead><tbody>${entries.map((a,i)=>`<tr><td><strong>${esc(a.code)} · ${esc(a.name)}</strong><small>${a.requiresSignature?'Con firma':'Sin firma'} · Cotejo pendiente</small><small>Apertura Moodle: ${esc(a.sourceOpenedAt||'—')}</small><small>Cierre Moodle: ${esc(a.sourceClosesAt||'—')}</small></td><td><input type="date" id="batchImportClass-${i}" value="${esc(a.classAt||'')}" aria-label="Día de clase ${esc(a.code)}"></td><td><input type="date" id="batchImportDue-${i}" value="${esc(a.dueAt||'')}" aria-label="Fecha límite ${esc(a.code)}"></td></tr>`).join('')}</tbody></table></div><p class="context-note">Si dejas una fecha vacía, la aplicación la mostrará pendiente; no se infiere el día de clase a partir de la apertura. Para las actividades ya cargadas, marca Actualizar solo las fechas. Revisa el día de clase antes de guardar.</p>`,async()=>{target=$('batchImportGroup').value;const g=db.groups.find(g=>g.id===target),pid=$('batchImportPeriod').value,cid=$('batchImportCategory').value;if(!g||!pid||!cid)throw Error('Selecciona grupo, parcial y categoría.');const updateExisting=$('batchUpdateExisting').checked,codes=new Set();for(const a of entries){const matches=db.activities.filter(x=>!x.trashId&&x.groupId===target&&x.periodId===pid&&x.code===a.code);if(codes.has(a.code)||matches.length>1||matches.length&&!updateExisting)throw Error('El código '+a.code+' ya existe o se repite. Para actualizar fechas marca Actualizar solo las fechas.');codes.add(a.code)}await mutate(d=>{entries.forEach((a,i)=>{const classAt=$('batchImportClass-'+i).value,dueAt=$('batchImportDue-'+i).value;for(const date of [classAt,dueAt])if(date&&Aula.dateDay(date)===null)throw Error('Revisa las fechas de '+a.code);const existing=d.activities.find(x=>!x.trashId&&x.groupId===target&&x.periodId===pid&&x.code===a.code);if(existing&&updateExisting){Object.assign(existing,{classAt,dueAt,sourceOpenedAt:a.sourceOpenedAt||'',sourceClosesAt:a.sourceClosesAt||''});return}d.activities.push({id:Aula.id(),subjectId:g.subjectId,groupId:g.id,periodId:pid,categoryId:cid,code:a.code,name:a.name,type:a.type,requiresSignature:a.requiresSignature,weight:1,total:100,criteria:[],quickNotes:Aula.clone(d.settings.quickNotes),lateRule:Aula.lateRule(),publishedAt:'',classAt,dueAt,sourceOpenedAt:a.sourceOpenedAt||'',sourceClosesAt:a.sourceClosesAt||''})})});subject=g.subjectId;group=g.id;period=pid;view='activities';render()},'Guardar actividades');function destinations(){target=$('batchImportGroup').value;const g=db.groups.find(g=>g.id===target),sub=db.subjects.find(s=>s.id===g?.subjectId),ps=list('periods').filter(p=>p.subjectId===sub?.id),match=ps.find(p=>Aula.norm(p.name).replace(/\D/g,'')===String(input.defaults?.period||''));$('batchImportPeriod').innerHTML=options(ps,match?.id||'','Selecciona parcial');$('batchImportCategory').innerHTML=options((sub?.evaluation.categories||[]).filter(c=>c.kind==='activity'),sub?.evaluation.categories.find(c=>c.kind==='activity')?.id||'','Selecciona categoría');$('modalGroupBadge').hidden=!g;if(g)$('modalGroupBadge').innerHTML=groupTag(g.name)}$('batchImportGroup').onchange=destinations;destinations()}
